{
  "rules": [
    {
      "statement": "Each step, the earliest priority deadline counts down by 1 if any priority messages are waiting; otherwise it resets to -1.",
      "kind": "transition",
      "action": "*",
      "when": "obs.priority_waiting > 0",
      "effects": {
        "next_deadline": "obs.next_deadline - 1"
      }
    },
    {
      "statement": "When no priority messages are waiting, the deadline indicator shows -1.",
      "kind": "transition",
      "action": "*",
      "when": "obs.priority_waiting == 0",
      "effects": {
        "next_deadline": "-1"
      }
    },
    {
      "statement": "Each wait step adds one new regular message to the queue.",
      "kind": "transition",
      "action": "wait",
      "when": "True",
      "effects": {
        "queue": "obs.queue + 1"
      }
    },
    {
      "statement": "Prioritize converts up to 3 regular messages into priority messages, but never more than the queue holds.",
      "kind": "transition",
      "action": "prioritize",
      "when": "True",
      "effects": {
        "queue": "obs.queue - min(3, obs.queue)",
        "priority_waiting": "obs.priority_waiting + min(3, obs.queue)"
      }
    },
    {
      "statement": "Sending via buoy delivers up to n messages (limited by queue and buoy signal), consumes 1 energy per message sent, and may lose messages if signal is weak.",
      "kind": "transition",
      "action": "send",
      "when": "args.via == 'buoy'",
      "effects": {
        "queue": "obs.queue - min(args.n, obs.queue, obs.buoy_signal)",
        "delivered": "obs.delivered + min(args.n, obs.queue, obs.buoy_signal)",
        "vessel_energy": "obs.vessel_energy - min(args.n, obs.queue, obs.buoy_signal)",
        "buoy_signal": "max(obs.buoy_signal - 1, 0)",
        "lost": "obs.lost + max(0, min(args.n, obs.queue) - obs.buoy_signal)"
      }
    },
    {
      "statement": "Sending via satellite delivers up to n messages (limited by queue), consumes 3 energy per message sent, and never loses messages.",
      "kind": "transition",
      "action": "send",
      "when": "args.via == 'sat'",
      "effects": {
        "queue": "obs.queue - min(args.n, obs.queue)",
        "delivered": "obs.delivered + min(args.n, obs.queue)",
        "vessel_energy": "obs.vessel_energy - 3 * min(args.n, obs.queue)"
      }
    },
    {
      "statement": "When sending, priority messages are delivered first up to the number of messages sent, increasing priority_delivered and decreasing priority_waiting.",
      "kind": "transition",
      "action": "send",
      "when": "True",
      "effects": {
        "priority_waiting": "max(obs.priority_waiting - min(args.n, obs.queue), 0)",
        "priority_delivered": "obs.priority_delivered + min(obs.priority_waiting, min(args.n, obs.queue))"
      }
    }
  ],
